import java.util.*;
class ProductRef { final String id; ProductRef(String id){this.id=id;} }
class Reviewer { final ProductRef reviewing; Reviewer(ProductRef p){reviewing=p;} }
class Portfolio { final List<ProductRef> products; Portfolio(List<ProductRef> p){products=p;} }
public class RelationshipDemo {
    public static void main(String[] args) {
        ProductRef p = new ProductRef("ORTHO");
        Reviewer r = new Reviewer(p);
        Portfolio portfolio = new Portfolio(List.of(p));
        System.out.println(r.reviewing.id + ":" + portfolio.products.get(0).id);
    }
}
